let s={lang:"sl",active:false,max:9,rounds:3,round:1,dice:2,open:[],sel:[],target:null,rolled:false,results:[],penalty:0,switches:0,rolling:false,perfect:false};
const tr=k=>(D[s.lang]||D.en)[k]||k;
const isMobile=()=>window.matchMedia("(max-width:650px)").matches;
const isIOS=()=>/iPad|iPhone|iPod/.test(navigator.userAgent)||(navigator.platform==="MacIntel"&&navigator.maxTouchPoints>1);
const telemetry=(event,payload={})=>{try{window.LBCBackend?.track?.(event,payload)}catch(e){}};
const onlineHook=(method,payload={})=>{try{window.LBCBackend?.online?.[method]?.(payload)}catch(e){}};
function translate(){document.documentElement.lang=s.lang;document.documentElement.dir=["ar","he"].includes(s.lang)?"rtl":"ltr";document.querySelectorAll("[data-t]").forEach(e=>e.textContent=tr(e.dataset.t));$("help").setAttribute("aria-label",tr("help"));$("help").title=tr("help");if(!$("helpOverlay").hidden)renderHelp()}
function renderHelp(){let h=H[s.lang]||H.en;$('helpTitle').textContent=h.title;$('helpBody').innerHTML=`<section><h3>${h.goal}</h3><p>${h.goalText}</p></section><section><h3>${h.start}</h3><p>${h.startText}</p></section><section><h3>${h.turn}</h3><p>${h.turnText}</p></section><section><h3>${h.dice}</h3><p>${h.diceText}</p></section><section><h3>${h.rounds}</h3><p>${h.roundsText}</p></section><section><h3>${h.perfect}</h3><p>${h.perfectText}</p></section><section><h3>${h.tip}</h3><p>${h.tipText}</p></section>`}
function openHelp(){renderHelp();$('helpOverlay').hidden=false}
function closeHelp(){$('helpOverlay').hidden=true}
function arrangeMobile(){if(isMobile()){let sw=$('diceSwitch'),layout=$('playArea');if(sw&&layout&&layout.nextElementSibling!==sw)layout.after(sw)}}
function focusPlay(){if(!isMobile())return;arrangeMobile();requestAnimationFrame(()=>{let c=document.querySelector('.controls');if(!c)return;let offset=isIOS()?72:18;let top=c.getBoundingClientRect().top+window.scrollY-offset;window.scrollTo({top:Math.max(0,top),behavior:'smooth'})})}
function setPlaying(v){$('game').classList.toggle('mobile-playing',v&&isMobile());if(v)focusPlay()}
function setMsg(x){$("message").textContent=x}
function lockSetup(v){["name","mode","rounds"].forEach(id=>$(id).disabled=v);$("start").disabled=v}
function read(){s.max=+$("mode").value;s.rounds=+$("rounds").value;s.dice=defaultDice[s.max]}
function startMatch(){read();s.active=true;s.round=1;s.results=[];lockSetup(true);$("new").disabled=true;startRound();renderResults();setPlaying(true);telemetry("start_match",{box:s.max,rounds:s.rounds,language:s.lang});onlineHook("matchStarted",{box:s.max,rounds:s.rounds,round:s.round})}
function startRound(){s.open=Array.from({length:s.max},(_,i)=>i+1);s.sel=[];s.target=null;s.rolled=false;s.penalty=0;s.switches=0;s.rolling=false;s.perfect=false;s.dice=defaultDice[s.max];$("diceChoice").value=s.dice;$("diceChoice").disabled=false;$("change").disabled=false;$("roll").disabled=false;$("close").disabled=true;$("next").hidden=true;$("dice").innerHTML="";$("target").textContent="–";$("selected").textContent="0";renderTiles();update();setMsg(`${tr("round")} ${s.round}/${s.rounds}. ${tr("begin")}`);$("ai").textContent="🤖"}
function renderTiles(){$("tiles").innerHTML="";for(let i=1;i<=s.max;i++){let e=document.createElement("div"),o=s.open.includes(i),q=s.sel.includes(i);e.className="tile "+(o?"open":"closed")+(q?" selected":"");e.textContent=i;if(o)e.onclick=()=>toggle(i);$("tiles").appendChild(e)}}
function toggle(n){if(!s.rolled||s.rolling)return;s.sel=s.sel.includes(n)?s.sel.filter(x=>x!==n):[...s.sel,n];$("selected").textContent=sum(s.sel);$("close").disabled=sum(s.sel)!==s.target;renderTiles()}
function combo(nums,w){function f(i,t){if(t===w)return true;if(t>w||i===nums.length)return false;return f(i+1,t+nums[i])||f(i+1,t)}return f(0,0)}
function flatDie(v){let f=document.createElement("div");f.className="flatDie";pips[v].forEach(p=>{let d=document.createElement("span");d.className="pip "+p;f.appendChild(d)});return f}
function cube(v){let w=document.createElement("div");w.className="cubeWrap rolling";let c=document.createElement("div");c.className="cube";[["front",3],["back",4],["right",2],["left",5],["top",1],["bottom",6]].forEach(([cl,n])=>{let f=document.createElement("div");f.className="face "+cl;pips[n].forEach(p=>{let d=document.createElement("span");d.className="pip "+p;f.appendChild(d)});c.appendChild(f)});let flat=flatDie(v);flat.hidden=true;w.appendChild(c);w.appendChild(flat);requestAnimationFrame(()=>c.style.transform=`rotateX(${720+Math.random()*360}deg) rotateY(${720+Math.random()*360}deg)`);setTimeout(()=>{w.classList.remove("rolling");c.hidden=true;flat.hidden=false},820);return w}
function showDice(vals){$("dice").innerHTML="";vals.forEach(v=>$("dice").appendChild(cube(v)))}
function provoke(){let p=$("persona").value,a=A[s.lang]||A.en,m=a[p]||a.friend;$("ai").textContent=p==="silent"?"":"🤖 "+m[Math.floor(Math.random()*m.length)]}
async function roll(){if(!s.active||s.rolling||s.rolled)return;focusPlay();s.rolling=true;$("roll").disabled=true;$("change").disabled=true;$("diceChoice").disabled=true;let vals=Array.from({length:s.dice},()=>1+Math.floor(Math.random()*6));showDice(vals);await sleep(900);s.target=sum(vals);s.rolled=true;s.rolling=false;$("target").textContent=s.target;if(!combo(s.open,s.target))finish(`${tr("nomove")}: ${s.target}.`);else{setMsg(`${tr("choose")} ${s.target}.`);provoke()}}
function closeNums(){if(sum(s.sel)!==s.target)return;s.open=s.open.filter(n=>!s.sel.includes(n));s.sel=[];s.target=null;s.rolled=false;$("target").textContent="–";$("selected").textContent="0";$("dice").innerHTML="";$("close").disabled=true;renderTiles();update();if(!s.open.length){s.perfect=true;finish(tr("perfect"))}else{$("roll").disabled=false;$("change").disabled=s.switches>=3;$("diceChoice").disabled=s.switches>=3;setMsg(tr("ok"))}}
function changeDice(){if(!s.active||s.rolled||s.rolling)return;let n=+$("diceChoice").value;if(n===s.dice){setMsg(tr("differentDice"));return}if(s.switches>=3)return;s.penalty+=penaltySteps[s.switches];s.switches++;s.dice=n;update();setMsg(`${tr("switchDone")}: +${s.penalty}.`);$("ai").textContent="🤖 "+((A[s.lang]||A.en).paid);if(s.switches>=3){$("change").disabled=true;$("diceChoice").disabled=true}}
function finish(reason){s.rolled=false;s.rolling=false;$("roll").disabled=true;$("close").disabled=true;$("change").disabled=true;$("diceChoice").disabled=true;let r=sum(s.open)+s.penalty;s.results.push(r);renderResults();update();onlineHook("progress",{round:s.round,roundScore:r,total:sum(s.results),rounds:s.rounds});if(s.perfect)celebrate();if(s.round>=s.rounds){s.active=false;setPlaying(false);lockSetup(false);$("new").disabled=false;$("next").hidden=true;let t=sum(s.results);saveBest(t);setMsg(`${reason} ${tr("end")}: ${t}.`);telemetry("finish_match",{box:s.max,rounds:s.rounds,total:t,language:s.lang});onlineHook("matchFinished",{total:t,box:s.max,rounds:s.rounds})}else{$("next").hidden=false;setMsg(`${reason} ${tr("score")}: ${r}.`)}}
function nextRound(){s.round++;startRound();renderResults();focusPlay()}
function renderResults(){$("results").innerHTML="";for(let r=1;r<=s.rounds;r++){let e=document.createElement("div");e.className="roundRow"+(r===s.round&&s.active?" current":"");e.innerHTML=`<span>${tr("round")} ${r}</span><b>${s.results[r-1]??"–"}</b>`;$("results").appendChild(e)}$("sum").textContent=sum(s.results);loadBest()}
function update(){$("player").textContent=$("name").value.trim()||tr("player");$("round").textContent=`${s.round}/${s.rounds}`;$("diceCount").textContent=s.dice;$("penalty").textContent=s.penalty;$("total").textContent=sum(s.results);$("score").textContent=sum(s.open)+s.penalty}
function key(){return`lbc-best-${s.max}-${s.rounds}`}function saveBest(v){let o=+localStorage.getItem(key());if(!o||v<o)localStorage.setItem(key(),v);loadBest()}function loadBest(){$("best").textContent=localStorage.getItem(key())||"–"}
function celebrate(){$("celebrateTitle").textContent=tr("perfect");$("celebrateText").textContent=$("name").value;$("celebrate").hidden=false;for(let i=0;i<50;i++){let c=document.createElement("div");c.className="confetti";c.style.left=Math.random()*100+"vw";c.style.background=`hsl(${Math.random()*360} 80% 60%)`;c.style.animationDelay=Math.random()*.7+"s";document.body.appendChild(c);setTimeout(()=>c.remove(),3500)}}
$("lang").onchange=e=>{s.lang=e.target.value;translate();renderResults();update();try{window.LBCBackend?.translateExtras?.(s.lang)}catch(err){}};$("start").onclick=startMatch;$("roll").onclick=roll;$("close").onclick=closeNums;$("next").onclick=nextRound;$("new").onclick=startMatch;$("change").onclick=changeDice;$("ok").onclick=()=>$("celebrate").hidden=true;$("help").onclick=openHelp;$("helpClose").onclick=closeHelp;$("helpOk").onclick=closeHelp;$("helpOverlay").onclick=e=>{if(e.target===$("helpOverlay"))closeHelp()};window.addEventListener("resize",arrangeMobile);translate();arrangeMobile();renderResults();update();loadBest();
